# backend.tf
terraform {
  backend "s3" {
    bucket = "satish-tf-state"
    key    = "capstone/terraform.tfstate"
    region = "us-east-1"
    encrypt = true
    dynamodb_table = "terraform-locks"
  }
}

# modules/s3-bucket/main.tf
resource "aws_s3_bucket" "this" { bucket = var.bucket_name; tags = var.tags }
resource "aws_s3_bucket_versioning" "this" {
  bucket = aws_s3_bucket.this.id
  versioning_configuration { status = "Enabled" }
}

# Call the module twice
module "raw"       { source = "./modules/s3-bucket"; bucket_name = "satish-raw-${var.env}" }
module "processed" { source = "./modules/s3-bucket"; bucket_name = "satish-proc-${var.env}" }

output "raw_arn" { value = module.raw.arn }
